entries[21273] = { ["name"] = "Blessed Qiraji Acolyte Staff", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Staff\n132 - 227 Damage Speed 3.00\n(59.83 damage per second)\n+32 Stamina\n+33 Intellect\nDurability 120 / 120\nRequires Level 60\nEquip: Increases damage and healing done by magical spells and effects by up to 76.\n\nEquip: Increases your spell hit rating by 16.\n\nEquip: Increases your spell critical strike rating by 14.\n\"The weapon is infused and reinforced with Elementium.\"\nSell Price:" }
entries[21275] = { ["name"] = "Blessed Qiraji Augur Staff", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Staff\n132 - 227 Damage Speed 3.00\n(59.83 damage per second)\n+23 Stamina\n+24 Intellect\nDurability 120 / 120\nRequires Level 60\nEquip: Increases healing done by up to 143 and damage done by up to 48 for all magical spells and effects.\n\nEquip: Restores 15 mana per 5 sec.\n\"The weapon is infused and reinforced with Elementium.\"\nSell Price:" }
entries[21277] = { ["name"] = "Tranquil Mechanical Yeti", ["text"] = "Binds when used\nUse: Right Click to summon and dismiss your Tranquil Mechanical Yeti.\nSell Price:" }
entries[21278] = { ["name"] = "Stormshroud Gloves", ["text"] = "Binds when equipped\nHands Leather\n99 Armor\nDurability 35 / 35\nRequires Level 50\nEquip: Improves hit rating by 10.\nEquip: Improves critical strike rating by 19.\n\nStormshroud Armor (0/4)\nStormshroud Armor\nStormshroud Pants\nStormshroud Shoulders\nStormshroud Gloves\n(2) Set : 5% chance of dealing 15 to 25 Nature damage on a successful melee attack. (Proc chance: 5%)\n(3) Set : 2% chance on melee attack of restoring 30 energy. (Proc chance: 2%)\n(4) Set : Increases attack power by 14.\nSell Price:" }
entries[21279] = { ["name"] = "Tome of Fireball XII", ["text"] = "Classes: Mage\nRequires Level 60\nUse: Teaches Fireball (Rank 12).\n\nHurls a fiery ball that causes 611 to 776 Fire damage and an additional 76 Fire damage over 8 sec.\nSell Price:" }
