entries[21281] = { ["name"] = "Grimoire of Shadow Bolt X", ["text"] = "Classes: Warlock\nRequires Level 60\nUse: Teaches Shadow Bolt (Rank 10).\n\nSends a shadowy bolt at the enemy, causing 497 to 554 Shadow damage.\nSell Price:" }
entries[21282] = { ["name"] = "Grimoire of Immolate VIII", ["text"] = "Classes: Warlock\nRequires Level 60\nUse: Teaches Immolate (Rank 8).\n\nBurns the enemy for 299 Fire damage and then an additional 510 Fire damage over 15 sec.\nSell Price:" }
