entries[21289] = { ["name"] = "Libram: Blessing of Might VII", ["text"] = "Classes: Paladin\nRequires Level 60\nUse: Teaches Blessing of Might (Rank 7).\n\nPlaces a Blessing on the friendly target, increasing attack power by 185 for 10 min. Players may only have one Blessing on them per Paladin at any one time.\nSell Price:" }
