entries[21302] = { ["name"] = "Handbook of Deadly Poison V", ["text"] = "Classes: Rogue\nRequires Level 60\nUse: Teaches Deadly Poison (Rank 5).\n\nCoats a weapon with poison that lasts for 1 hour.\nEach strike has a 30% chance of poisoning the enemy for 136 Nature damage over 12 sec. Stacks up to 5 times on a single target.\nSell Price:\nDeadly Poison V\nClasses: Rogue\nRequires Level 60\n\nUse: Coats a weapon with poison that lasts for 1 hour.\nEach strike has a 30% chance of poisoning the enemy for 136 Nature damage over 12 sec. Stacks up to 5 times on a single target. (Proc chance: 30%)\nSell Price:\nRequires Deathweed (2), Crystal Vial" }
